#[tokio::test]
async fn an_identical_receipt_replays_but_changed_receipt_content_is_refused() {
    let Some(database_url) = database_url() else {
        eprintln!("skipping: ACKPLANE_TEST_DATABASE_URL is not set");
        return;
    };
    let suffix = unique_id("work-command-receipt");
    let tenant_id = format!("tenant-{suffix}");
    let repository_id = format!("repository-{suffix}");
    let command = request(&tenant_id, &repository_id, &suffix);
    let now = SystemTime::now();
    let mut store = WorkCommandStore::connect(&database_url)
        .await
        .expect("the command store should connect");
    store
        .record_request(&command, now)
        .await
        .expect("the command should persist before its receipt");
    let original = receipt(
        &tenant_id,
        &repository_id,
        &command.command_id,
        &suffix,
        now,
    );
    let mut changed = original.clone();
    changed.reason = "Attempt to rewrite an immutable receipt.".to_owned();

    let first = store
        .record_receipt(&original, now)
        .await
        .expect("the first receipt should persist");
    let replay = store
        .record_receipt(&original, now)
        .await
        .expect("the identical receipt should replay");
    let conflict = store.record_receipt(&changed, now).await;

    assert!(!first.idempotent_replay);
    assert!(replay.idempotent_replay);
    assert_eq!(replay.receipt, first.receipt);
    assert!(matches!(
        conflict,
        Err(WorkCommandStoreError::ReceiptConflict)
    ));
}

